insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 1, 'The ESP motor on the Ekene register states 2 failures a year, a lead time of 150 days and 365 days a year. What mean number of orders outstanding does the engine''s insurance spares call return?', '["300, the failures a year times the lead time in days with no conversion to years", "0.439588, the probability that no replacement order is on its way at all", "0.821918, the failures a year times the lead time in days over the days a year", "0.261506, the expected units down once a single spare sits on the shelf"]'::jsonb, 2, 'The one-for-one model makes the orders outstanding Poisson with a mean of failuresPerYear x leadTimeDays / daysPerYear: 2 times 150 over 365 is 0.821918 (engine). 300 forgets to turn days into a fraction of a year; 0.439588 is the probability of no shortage with no spares, the chance that nothing is outstanding; 0.261506 is the expected units down with one spare.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 2, 'Which picture does the engine''s one-for-one insurance model draw of a failure?', '["The failed unit takes a spare and one replacement order goes out, arriving one lead time later", "The failed unit goes to a workshop, is repaired and returns to the shelf after a repair time", "Failures are pooled and replaced in one batch sized by the economic order quantity each year", "A spare is drawn only at the next stock review, and the order covers the whole review period"]'::jsonb, 0, 'Each failure takes a spare and places exactly one order, which arrives after the stated lead time; that is what one for one means, and it makes the orders outstanding Poisson. A repair loop is a different model the course names and leaves out; batching by EOQ and ordering at a review belong to the ordered and stocked items of the lower tiers.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 3, 'Each ESP motor costs 185000 and the stated holding rate is 0.2. What holding cost does one more spare add each year in the engine''s table?', '["185000.000000 a year, the whole unit cost charged again every year", "74000.000000 a year, which is the holding charge of the first two spares", "18000 a year, the one downtime cost a day that the register states", "37000.000000 a year, the unit cost times the holding rate"]'::jsonb, 3, 'The holding charge is unitCost x holdingRate for each spare bought: 185000 times 0.2 is 37000.000000 a year, and the holding column rises by that step each row. 185000.000000 is the holding cost of five spares; 74000.000000 is that of two; 18000 is the downtime cost a day, a different input.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 4, 'With no spares on the shelf, what downtime cost a year does the engine return for the ESP motor at 18000 a day?', '["1718091.849237, the downtime the table prints once one spare is held back", "5400000.000000, the mean units down times 365 days times 18000 a day", "1755091.849237, the total cost a year at one spare, its holding included", "160003.732064, the lowest total cost a year anywhere in the whole search"]'::jsonb, 1, 'With no spares every order outstanding is a unit down, so the expected units down are the mean 0.821918, and the engine prices them at daysPerYear x downtimeCostPerDay: 5400000.000000 a year. 1718091.849237 is the downtime with one spare; 1755091.849237 is the one-spare total; 160003.732064 is the cheapest total, at four spares.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 5, 'Searching 0 to 6 spares, which stock of ESP motors does the engine return as the cheapest, and at what total cost a year?', '["3 spares, at a total cost of 188347.405085 a year each", "4 spares, at a total cost of 160003.732064 a year", "6 spares, the most searched, at 222179.621332 a year", "5 spares, at a total cost of 186577.882952 a year, all in"]'::jsonb, 1, 'The engine prices every number from 0 to 6 and takes the lowest total: 4 spares at 160003.732064 a year (engine), inside the search, so no limit flag is raised. Three spares cost 188347.405085 and five cost 186577.882952, both above it; six is the dearest of the upper rows at 222179.621332 and is not chosen for being the largest.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 6, 'Why is a fifth ESP motor spare not worth holding at the stated costs?', '["Its no-shortage probability of 0.999787 is above the 0.99 the engine aims for", "The engine stops at the first row whose fill rate reaches 0.99, which is the fourth", "Five spares would exceed the 2 failures a year more than twice over, and the model caps it", "It adds 37000.000000 of holding a year and saves only 10425.849112 of downtime"]'::jsonb, 3, 'The marginal comparison is holding against the downtime saved: from four spares to five the downtime falls by 10425.849112 a year while the holding rises by 37000.000000, so the total rises. The engine aims at no probability and stops at no fill rate; it prices every row. No cap ties the spares to the failures a year.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 7, 'The same ESP motor case is run with a downtime cost of 100 a day. What does the engine''s reason say?', '["0 spares: holding 0 a year against expected downtime 30000, total 30000, the lowest for 0 to 6; one more spare adds 37000 of holding and saves 20455.05 of downtime", "4 spares: holding 148000 a year against expected downtime 12003.73, total 160003.73, the lowest for 0 to 6; one more spare adds 37000 of holding and saves 10425.85 of downtime", "downtimeCostPerDay must be a finite number at or above 0; got 100, since a figure below the unit cost cannot be priced", "1 spare: holding 37000 a year against expected downtime 1718091.85, total 1755091.85, the lowest for 0 to 1; the search stopped at maxSpares 1"]'::jsonb, 0, 'At 100 a day the first spare costs 37000 of holding and saves only 20455.05 of downtime, so the engine keeps none; its reason, verbatim, is the keyed one. The four-spare reason belongs to 18000 a day; 100 is a valid cost and draws no refusal; the one-spare reason belongs to a search limit of 1.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 8, 'A planner types a downtime cost of -1 a day into the ESP motor case. What does the engine return, in its own words?', '["a result of 0 spares: negative waiting makes the empty shelf cheapest", "downtimeCostPerDay must be a finite number above 0; got -1", "downtimeCostPerDay must be a finite number at or above 0; got -1", "a result of 6 spares, flagged at the search limit"]'::jsonb, 2, 'A negative downtime cost would reward failure, so the engine refuses it by name, and the keyed message is its own words. It returns no result on a refused input. The refusal allows 0 (at or above 0), so a message demanding a figure above 0 is not the engine''s.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 9, 'A supplier promises instant replacement, so a planner enters a lead time of 0 days for the ESP motor. How does the engine respond?', '["a mean of 0 orders outstanding and 0 spares at no cost, since nothing is ever on order", "leadTimeDays must be at most 260.714285; got 0, since a lead time is capped at both of its ends", "a one-row table: an instant replacement needs no search, and the shelf stays empty", "leadTimeDays must be a finite number above 0; got 0, since an order that lands at once leaves nothing to size"]'::jsonb, 3, 'A replacement that arrives the instant it is ordered leaves nothing outstanding, and the engine refuses the input; the keyed message is its own words. It computes no mean and no table on a refused input. The message about 260.714285 is the cap on a lead time that is too long, which 0 is not.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 10, 'The ESP motor case is sent with daysPerYear left out. What happens?', '["A 365 day year is assumed, and the same four spares come back as they did before", "It is refused by name, since no input of the insurance call has a default", "The engine assumes a 360 day costing year and returns a slightly higher mean to match", "A mean of 300 orders outstanding, with the lead time read in years by the engine"]'::jsonb, 1, 'Every input of the insurance call is stated with no default, and a missing one is refused by name, here in the engine''s words daysPerYear must be a finite number above 0; got undefined. The engine assumes no year length of any kind, 365 or 360, and it never reinterprets the lead time.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 11, 'Which input of the ESP motor case does the engine convert from one unit into another?', '["Only the lead time, from days into a fraction of a year, through the stated days a year", "Failures a year, into failures a day, through a fixed calendar that the engine holds itself", "The downtime cost a day, into a cost a year, through a 360 day costing year the engine assumes", "The unit cost, into a cost a day, so that it can be compared with the downtime cost"]'::jsonb, 0, 'The mean is failuresPerYear x leadTimeDays / daysPerYear: the stated days a year turn the lead time into years, and nothing else is converted. The engine holds no calendar of its own; it prices downtime with the stated daysPerYear; and holding is the unit cost times the holding rate a year.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 12, 'The insurance call returns a reading beside its rule. What does that reading state?', '["each failure costs downtimeCostPerDay once, however long it waits; the holding charge falls on the spares still on the shelf", "a unit waiting for a spare loses part of its production, costed at a stated share of downtimeCostPerDay a day", "each unit waiting for a spare is one unit down, costed at downtimeCostPerDay; the holding charge falls on all n spares bought", "the holding charge falls on the spares on the shelf only, and a spare in use while its order is outstanding costs nothing"]'::jsonb, 2, 'The engine''s reading, verbatim, is the keyed one: each waiting unit is one unit down for as long as it waits, and every spare bought carries the holding charge. A charge per failure event, a partial production loss and holding on shelf stock only are the alternatives a planner would have to state as a different model.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 13, 'A plant repairs its failed motors in a workshop. Which of these lies outside the engine''s model?', '["A holding charge that falls on every spare that has been bought for the unit", "A repair loop, condemnation, multi-echelon stock and partial production loss", "The Poisson distribution of the orders outstanding at a random moment", "The downtime cost of one unit down for one day while it waits for a spare"]'::jsonb, 1, 'The model holds no repair loop, no condemnation, no multi-echelon stock and no partial production loss; each is a different model and a different course. The holding charge, the Poisson orders outstanding and the downtime cost a day are the three pieces the model is built from.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 14, 'In this course, what does the phrase "insurance spare" mean?', '["Any spare kept on the shelf just in case, whatever the reason it was bought or the model behind it", "Every spare of an item that the stated criticality policy places in class V, whatever its cost may be", "Any spare of an item ranked in class A by its annual usage value under the stated cut-offs and rule", "A spare sized by the stated one-for-one model at a stated failure rate, lead time and downtime cost"]'::jsonb, 3, 'The course legislates the term: an insurance spare is always of the stated one-for-one model. Everyday usage, a criticality class and an ABC class each say something about an item, and none of them sizes a spare.'),
  ('materials', 'advanced', 'module', 'm01-insurance-spares', 15, 'The engine returns 4 spares as the ESP motor''s cheapest stock. Which reading of that answer does the course accept?', '["It is the cheapest stock for the stated failure rate and costs, and it is quoted with those inputs", "It is a forecast that four ESP motors will fail within the costing year across the pumped wells", "It is the stock the engine chose to meet a no-shortage probability of 0.998413 as its stated target", "It is an audit finding that the register''s 1 motor on hand is short by 3 against the policy"]'::jsonb, 0, 'A number of spares is the cheapest for the stated failure rate and costs, and none is a forecast of what will fail, a target it aimed at, or an audit of the register. The 0.998413 is a consequence of four spares; the 1 on hand is a separate fact the model does not read.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 1, 'MIL-HDBK-338B (1 October 1998) example 5.3.8.1 runs a slide projector for 500 hours with a lamp failure rate of 0.001 failures per hour. What Poisson mean does that give?', '["2 failures, the number of spare bulbs the example holds on hand", "0.500000 failures, the rate an hour times the 500 hours of the mission", "0.365 failures, the figure a year that the orders outstanding case states", "500 failures, the hours of operation read directly as the expected count"]'::jsonb, 1, 'A rate of 0.001 an hour over 500 hours is a mean of 0.500000 failures (engine). The 2 is the stock of spare bulbs, the level the probability is asked at; 0.365 is the failures a year of the restated insurance case, one input of its mean; 500 is the length of the mission.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 2, 'For the handbook lamps, what probability of two failures or fewer does the engine return, and how does it stand against the handbook''s figure?', '["0.949374, which the handbook prints as 0.986 after a slip in its table", "0.986 exactly, because the engine is set up to reproduce the printed handbook figure", "0.990054, the three-spare figure, which the handbook rounds to 0.99", "0.985612 from the engine, which the handbook prints at three decimals as 0.986"]'::jsonb, 3, 'The Poisson cumulative probability at 2 with a mean of 0.500000 is 0.985612 (engine), and the handbook''s 0.986 is that figure at three decimals: a rounding, no slip. 0.949374 and 0.990054 are rows of the ESP motor table at another mean; the engine never changes a rule to match a print.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 3, 'The course restates the handbook lamps as orders outstanding in an insurance call. Which stated inputs give the lamp mean there?', '["0.365 failures a year and a lead time of 500 days over 365 days a year", "0.001 failures a year and a lead time of 500 days over 365 days a year", "2 failures a year and a lead time of 150 days over 365 days a year, as stated", "0.5 failures a year and a lead time of 365 days over 500 days a year"]'::jsonb, 0, '0.365 times 500 over 365 is a mean of 0.500000 orders outstanding, the lamp mean, and with two spares the probability of no shortage is 0.985612. 0.001 is the lamp rate an hour and gives no such mean here; 2 failures over 150 days is the ESP motor''s 0.821918; swapping the lead time and the days a year misstates the year.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 4, 'Why does the course anchor the insurance spares model to MIL-HDBK-338B?', '["Caplice lecture 13 prints a worked insurance-spares cost table, and the handbook is used only to confirm its prices", "Silver, Pyke and Thomas print the one-for-one cost example, and the handbook stands in for it because it is shorter", "No public text read for the course prints a worked insurance-spares cost example, so the course ties the model''s Poisson figure to the handbook", "The handbook prints holding and downtime costs for its spare lamps, which the engine reproduces to the cent in every row of its table"]'::jsonb, 2, 'The course states the one-for-one model as the engine''s model and anchors its Poisson probability to the handbook''s lamp example, because no public text it read prints a worked cost example. Lecture 13 is cited for the Poisson loss function; Silver, Pyke and Thomas were not read; the handbook prints a probability and no costs.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 5, 'Which description of MIL-HDBK-338B matches the way the course names and uses it?', '["Dated 1 October 1998, a US Department of Defense handbook in the public domain, quoted with its citation", "Dated Fall 2006, licensed CC BY-NC-SA 4.0, and so cited by its section and slide numbers only", "Dated June 2018, licensed CC BY-NC-ND 4.0, and named only for the P-label sentence it carries", "Dated February 1913, read in a 1990 reprint whose typesetting is copyright, so it is not reproduced"]'::jsonb, 0, 'MIL-HDBK-338B is dated 1 October 1998, is public domain (distribution A), and is quoted with its citation; it was read on 2026-09-27. Fall 2006 with CC BY-NC-SA 4.0 describes the MIT lectures; June 2018 with CC BY-NC-ND 4.0 is SPE-PRMS 2018; February 1913 and the 1990 reprint are Harris.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 6, 'With 4 ESP motor spares, which pair of probabilities does the engine''s table print?', '["No shortage 0.990054 and a fill rate of 0.998413", "No shortage 0.998413 and a fill rate of 0.990054", "No shortage 0.990054 and a fill rate of 0.949374", "No shortage 0.998413 and a fill rate of 0.998413"]'::jsonb, 1, 'With n spares the probability of no shortage is P(X <= n) and the fill rate is P(X <= n - 1): at four spares 0.998413 and 0.990054 (engine). Swapping them reverses the definitions; 0.990054 and 0.949374 are the row for three spares; the two measures differ by one row, so they do not agree.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 7, 'How does the engine define the fill rate of an insurance spare?', '["P(X <= n): the chance that n or fewer orders are outstanding at a random moment", "the fraction of cycles in which no unit is ever left waiting for a spare", "one less the expected units down divided by the failures a year that are stated", "P(X <= n - 1): the chance that a failure, when it comes, finds a spare"]'::jsonb, 3, 'The rule reads fill rate P(X <= n - 1), the chance a failure finds a spare: a spare is waiting only if fewer than n orders are outstanding when the failure comes. P(X <= n) is the probability of no shortage; a share of cycles is a cycle service measure; no ratio of units down to failures enters the rule.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 8, 'In the ESP motor table the fill rate with 3 spares and the no-shortage probability with 2 spares both print as 0.949374. How are the two figures related?', '["They print alike at six decimals only, and the course keeps them apart as two different figures", "They agree by chance on this motor''s inputs, and on another stated mean they would part company", "They are equal: the fill rate with n spares is the no-shortage probability with one spare fewer, row by row", "They differ further out, because one is measured per failure and the other per moment of time"]'::jsonb, 2, 'The engine returns the fill rate with n spares as the no-shortage probability with n less one, so the two are the same figure, row by row. Printed alike is not equal in general, and here the rule itself makes them equal; no choice of inputs separates them, whatever each one is said to measure.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 9, 'With no ESP motor spares held, what fill rate does the engine print?', '["0.000000: every failure waits, since there is no spare to find", "0.439588: the chance that no order is outstanding when a failure comes", "0.821918: the mean orders outstanding read in the place of a probability", "1.000000: with nothing on the shelf there is no stock left to run short"]'::jsonb, 0, 'With no spares the fill rate P(X <= -1) is 0.000000 (engine): no failure can find a spare. 0.439588 is the probability of no shortage with no spares, the chance nothing is outstanding; 0.821918 is the mean, and no probability; an empty shelf short on every failure has a fill rate of none at all.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 10, 'On the empty shelf, how many ESP motors does the engine expect to be down on average?', '["0.439588, the probability that no order is outstanding at a random moment", "0.261506, the figure the table prints on the row for one spare held", "1 unit, since a single failure leaves exactly one unit down at a time", "0.821918, the mean orders outstanding, every one of them a unit down"]'::jsonb, 3, 'Expected units down are E[(X - n)+], the orders outstanding beyond n; with n = 0 that is the mean, 0.821918 (engine). 0.439588 is a probability; 0.261506 belongs to one spare; the count of units down is Poisson, so its average is the mean and no fixed single unit.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 11, 'At the ESP motor''s cheapest stock of 4 spares, what are the expected units down and the downtime cost a year they carry?', '["0.011773 units down on average, priced at 77347.405085 a year", "0.001827 units down on average, priced at 12003.732064 a year", "0.001827 units down on average, priced at 148000.000000 a year", "0.000240 units down on average, priced at 1577.882952 a year"]'::jsonb, 1, 'The four-spare row prints 0.001827 expected units down and a downtime cost of 12003.732064 a year (engine). 0.011773 and 77347.405085 are the three-spare row; 148000.000000 is the four-spare holding cost; 0.000240 and 1577.882952 are the five-spare row.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 12, 'Working only from the printed columns of the ESP motor table, which step reproduces the expected units down with one spare, 0.261506?', '["0.821918 times 0.439588, the mean scaled down by the probability of no shortage at 0 spares", "0.821918 less 0.439588, the probability taken straight from the mean at 0", "0.821918 less one less 0.439588, the loss at 0 less the chance of more than 0 outstanding", "0.821918 less one less 0.800893, using the no-shortage figure of the same row"]'::jsonb, 2, 'The loss recursion subtracts one less the cumulative probability at the level before: 0.821918 less (1 less 0.439588) gives 0.261506, within a unit of the sixth decimal of the engine''s column. A product, a bare difference and the cumulative of the same row are not the recursion.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 13, 'A planner caps the ESP motor search at one spare. Which result comes back from the engine?', '["1 spare, with a reason that says the search stopped at maxSpares 1, so a larger stock may cost less", "A refusal naming maxSpares, since a limit below the mean''s cheapest stock cannot be searched", "4 spares, since the engine widens its own search until the cheapest stock lies inside it", "1 spare, reported as the proven cheapest stock with the flag for the search limit left false"]'::jsonb, 0, 'The search prices 0 and 1 only; the cheapest found sits on the limit, so the engine flags it and says a larger stock may cost less. That is a result with a reason, and no refusal. The engine never widens its own search, and the flag is raised because the answer sits on the limit.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 14, 'What does the engine say when the search limit for the ESP motor is stated as 1.5?', '["maxSpares must be a whole number from 1 to 1000; got 1.5", "a result at 1 spare, the fraction 1.5 rounded down and flagged", "a result at 2 spares, the fraction rounded up", "maxSpares must be a whole number from 0 to 1000; got 1.5"]'::jsonb, 3, 'The search limit is a whole number from 0 to 1000, and a fraction is refused by name; the keyed message is the engine''s own words. The lower end is 0, so a message starting the range at 1 is not the engine''s, and the engine rounds no stated limit.'),
  ('materials', 'advanced', 'module', 'm02-the-poisson-anchor', 15, 'Is a search limit of 0 accepted on the ESP motor case, and what is returned?', '["A refusal, since a search limit of 0 leaves the engine nothing to search at all", "A result that prices the empty shelf alone: 0 spares, total 5400000, the lowest for 0 to 0", "A result of 0 spares with the reason saying a larger stock may cost less, flagged at the limit", "A result of 4 spares, the limit of 0 read as no limit on how far the engine searches"]'::jsonb, 1, 'A limit of 0 is accepted, and the engine''s reason, verbatim, is 0 spares: holding 0 a year against expected downtime 5400000, total 5400000, the lowest for 0 to 0. Zero is inside the range 0 to 1000, so there is no refusal, and a limit of 0 is read as stated; it opens no wider search.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 1, 'Of the engine''s nine functions, which one samples, and through what?', '["insuranceSpares and leadTimeRisk both, each one through a sampler written inside the inventory engine itself for its own use alone", "every function that takes a spread, through a normal sampler seeded from the system clock whenever no seed is typed in", "poissonStock and leadTimeRisk, through a Poisson sampler that lib/stats keeps right beside its triangular inverse CDF", "leadTimeRisk alone, through lib/stats: mulberry32 for the uniforms, triInvCDF for each value and basicStats for the percentiles"]'::jsonb, 3, 'The engine carries no sampler and no percentile code of its own; leadTimeRisk is the one function that samples, on the stated seed, through the canonical lib/stats pieces. insuranceSpares and poissonStock compute exact Poisson figures, the safety stock is closed form, and no seed is ever taken from a clock.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 2, 'For each draw of the mechanical seal, in what order does the engine spend its random numbers?', '["One uniform for the demand rate, then one for the lead time, each drawn from its own separate stream of numbers", "The lead time takes the first uniform of each draw and the rate the second, all from one mulberry32 stream", "One uniform for every day of the drawn lead time, each turned into that day''s demand rate", "Two uniforms averaged into one, which then sets both the lead time and the demand rate together for the draw"]'::jsonb, 1, 'The basis states it: per iteration a uniform for the lead time then one for the demand rate, from one mulberry32(20270301) stream, each through triInvCDF. The order is fixed, which is why a second run on the same seed returns the same draws. There are no separate streams, no daily draws and no shared uniform.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 3, 'How does the engine turn one draw of the seal into a lead-time demand?', '["Rate times days: the rate drawn for that draw, kept for every day of its drawn lead time", "A fresh demand draw is added for each day of the drawn lead time, so that the busy and quiet days offset each other", "It multiplies the modal demand of 0.016 a day by the drawn lead time, so only the lead time varies", "It divides the drawn lead time by the drawn demand rate to give the days that one seal lasts"]'::jsonb, 0, 'The lead-time demand for a draw is the rate times the days, and the rate holds for the whole lead time, as the basis says. A fresh demand draw every day is the alternative the course names; holding the demand at its mode would sample the lead time alone; a ratio of days to rate is no demand at all.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 4, 'A lead-time risk call on the mechanical seal leaves out the seed. What does the engine return?', '["a result drawn on seed 0, the first seed the sampler accepts, with the seed printed in the basis", "a result drawn on a seed taken from the clock, printed in the basis so that the run can be repeated", "seed must be a whole number from 0 to 4294967295; it is required so that every run can be reproduced", "seed must be a whole number from 1 to 200000; it is required so that every run can be reproduced"]'::jsonb, 2, 'The seed is a stated input with no default, and a call without one is refused by name; the keyed message is the engine''s own words. No seed is supplied for the user, from 0 or from a clock; 1 to 200000 is the range of the draw count.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 5, 'A planner asks for no sampling at all, an iteration count of 0. Which message or figure comes back?', '["iterations must be a whole number from 0 to 200000; got 0, since an empty run is read as no draws", "iterations must be a whole number from 1 to 200000; got 0, since a run needs at least one draw", "a result with every sampled figure at 0 and no stockout counted in any cycle", "a result on the 20000 draws that the Ekene case states for the mechanical seal"]'::jsonb, 1, 'The draw count is a whole number from 1 to the cap of 200000, and 0 is refused; the keyed message is the engine''s own words. The range starts at 1, so a message allowing 0 is not the engine''s; it returns no figures on a refused input and borrows no count from another case.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 6, 'On seed 20270301 and 20000 draws, what does the engine return as the P90 of the mechanical seal''s lead time, and how is it read?', '["83.198487 days, an estimate on that seed and those draws: the low figure, met or exceeded in 90 percent of draws", "134.894691 days, the high figure that 90 percent of the sampled lead times fall at or below on that same run, as P90", "106.453303 days, the mean lead time, which the engine prints under the P90 label for any sampled lead time it returns", "103.503359 days, the middle sorted draw, which is the figure a P90 names for a sampled lead time"]'::jsonb, 0, 'The P90 of a sampled lead time is the low figure, 83.198487 days on seed 20270301 and 20000 draws (engine), an estimate that is not graded. 134.894691 is the P10, the high figure; 106.453303 is the mean; 103.503359 is the P50.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 7, 'With n draws sorted from smallest to largest, at which index does the engine read the P90 of a sampled lead time?', '["floor(0.9 n), the 90th percentile of all the sorted draws", "floor(0.5 n), the middle one of all of the sorted draws", "ceil(0.95 x n) - 1, the index of the reorder point draw", "floor(0.1 n), the 10th percentile of the sorted draws"]'::jsonb, 3, 'The basis reads P90 = index floor(0.1 n), P50 = floor(0.5 n), P10 = floor(0.9 n). floor(0.9 n) is where the P10 is read; floor(0.5 n) is the P50; ceil(0.95 x n) - 1 is the index of the reorder point for a cycle service level of 0.95.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 8, 'For the seal''s lead-time demand, at which end of the sampled figures does the stockout risk sit, according to the engine''s basis?', '["At the P90 end, the high figure, since the 90th percentile is where demand runs out", "At the P50, since a reorder point is always set at the middle of the sampled demand", "At the P10 end, the high figure, since more demand over the lead time is worse for stock", "At the minimum, since the shortest lead times leave the least time to reorder"]'::jsonb, 2, 'The basis says the stockout risk sits at the P10 end: for a lead time or a demand the P10 is the high figure, 2.780743 seals for the seal on seed 20270301 and 20000 draws. The P90 is the low figure; the P50 is the middle; the shortest lead times carry the least demand.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 9, 'Every lead-time risk call returns the sentence "P90 means a 90% probability the actual quantity meets or exceeds this value, per SPE PRMS." How does this course treat SPE-PRMS 2018?', '["It is named only because the sentence names it; no sentence of it is quoted and the reserves and resources course teaches it", "It is quoted for its definitions of the percentiles, and the P-label sentence is its own wording of them, cited with its page", "It is the source of the triangular sampler and the seed, which the engine takes from an appendix of that document", "It sets the cycle service levels the spares calculator uses, which is why the sentence cites it by name"]'::jsonb, 0, 'SPE-PRMS 2018 (June 2018, CC BY-NC-ND 4.0) is named only, for the P-label sentence; no sentence of it is quoted; the prms course of the academy teaches the framework. The sentence is the platform''s one convention for P-labels from lib/conventions/percentile.js; the sampler is lib/stats; a cycle service level or fill rate is a stated input.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 10, 'The same seal on seed 20270302 with 2000 draws gives a stockout probability of 0.065500, where seed 20270301 with 20000 draws gives 0.058600. What does the difference show?', '["A slip in the second run, so the course keeps the first run as the engine''s true stockout rate", "A sampled figure is an estimate that moves with the seed and the draw count, which is why none is graded", "The seed changes the triangles the engine fits, so the two runs describe two different mechanical seals", "The two runs disagree because the engine rounds each estimate to four places before it is printed"]'::jsonb, 1, 'Each run is an estimate of the same quantities, and they differ because the draws differ; no graded figure is a Monte Carlo draw for that reason. Neither run is a slip; the seed moves no stated triangle; the reason prints the estimate with trailing zeros dropped, and the fields differ at six decimals too.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 11, 'A lead-time risk call states the seal''s lead time with a minimum of 90, a mode of 70 and a maximum of 160. What does the engine return?', '["a result on the triangle sorted into min 70, mode 90, max 160, with a note in the basis", "leadTimeDays.mode must be at or above leadTimeDays.min; got 70", "a result on a constant lead time of 70 days, the stated mode", "leadTimeDays must have min <= mode <= max; got min 90, mode 70, max 160"]'::jsonb, 3, 'A triangle needs its minimum at or below its mode and its mode at or below its maximum; out of order it is refused by name, and the keyed message is the engine''s own. The engine never reorders or replaces a stated input, and the message names leadTimeDays as a whole.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 12, 'What does the engine return when the seal''s demand a day has a minimum of -0.01?', '["demandPerDay.min must be a finite number above 0; got -0.01, naming the triangle''s lowest corner", "a result with the negative minimum read as 0 seals a day, the least there can be", "demandPerDay.min must be at or above 0; got -0.01, naming the term that carries the negative figure", "a result with the negative draws read as seals returned to stock, which lowers the count"]'::jsonb, 2, 'A negative demand is refused at the term that carries it, demandPerDay.min, and the keyed message is the engine''s own words. A demand of 0 a day is accepted, so a message asking for a figure above 0 is not the engine''s; the engine clips no stated input to 0 and reads no returns.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 13, 'Why does the engine sample through the canonical lib/stats Monte Carlo, with no sampler of its own?', '["So each call can pick the sampler that fits its inputs best, normal or triangular, without being told which to use", "So the same seed and draw count give the same draws anywhere on the platform, under one P-label convention", "So the lead-time figures can be graded, since a canonical sampler makes every estimate exact", "So the seed can be left out, since the canonical sampler supplies one that every course shares"]'::jsonb, 1, 'Using the platform''s one seeded sampler means the Monte Carlo here behaves as it does everywhere else: stated seed and draws, the same draws, one convention for the P-labels. The engine picks no distribution for the user, a sampled figure stays an estimate and is never graded, and the seed is always a stated input.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 14, 'When the course replayed the mechanical seal''s draws by hand from mulberry32 and triInvCDF on seed 20270301 with 20000 draws, what did it find?', '["1172 of 20000 draws with a lead-time demand above the reorder point 3, the engine''s own count", "1172 of 20000 draws at or above the reorder point 3, which the engine then counts as met", "1000 of 20000 draws above the reorder point, the count a stockout probability of 0.05 needs", "a count that differs from the engine''s, since a hand replay spends its uniforms in another order"]'::jsonb, 0, 'Replayed on seed 20270301, a lead-time uniform then a demand uniform per draw, each through triInvCDF, the 20000 draws give 1172 lead-time demands above the reorder point, the engine''s count. The engine counts demands above the point, and equality is met; no 1000 figure appears; the replay used the stated order.'),
  ('materials', 'advanced', 'module', 'm03-lead-time-risk-by-monte-carlo', 15, 'The seal''s lead time is a triangle of 70, 90 and 160 days. On seed 20270301 and 20000 draws, why does its sampled mean of 106.453303 days sit above the mode?', '["The sampler draws the lead time twice for each iteration and keeps whichever of the two is longer", "The mean includes the demand rate, which is added to the lead time before the draws are averaged", "The engine rounds each drawn lead time up to the next whole day before it averages them all", "The triangle''s long tail runs out to 160 days on the slow side, which pulls the mean above 90"]'::jsonb, 3, 'The lead-time triangle leans right: 90 to 160 is a longer tail than 70 to 90, so the mean, 106.453303 days on seed 20270301 and 20000 draws (an estimate), sits above the mode. The engine takes one uniform for the lead time a draw, keeps lead time and demand apart, and rounds no draw.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 1, 'A constant demand of 2 a day over a constant 10 days meets a reorder point of 20, on 50 draws and seed 1. What does the engine''s reason say?', '["50 of 50 draws have a lead-time demand at the reorder point 20: a stockout probability of 1 a cycle", "0 of 50 draws have a lead-time demand above the reorder point 20: a stockout probability of 0 a cycle", "25 of 50 draws have a lead-time demand above the reorder point 20, half the cycles on a tie", "leadTimeDays must be a triangular distribution { min, mode, max }; got 10 as a constant"]'::jsonb, 1, 'A stockout is a lead-time demand above the reorder point, and a demand equal to it is met: every draw is exactly 20, so the engine counts none, in the keyed words. Counting equality as a stockout is the alternative it names, which the engine does not apply; no tie is split; a constant is accepted as a plain number.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 2, 'The same constant case is run with a reorder point of 19.5. What does the engine return?', '["No stockout at all, since 19.5 rounds to the 20 the draws need over the lead time", "A stockout in half the draws, since 19.5 sits halfway between two whole units of stock", "A refusal, since a reorder point must be a whole number of units whenever demand is constant", "Every draw a stockout, 50 of 50, each 0.500000 short, a stockout probability of 1 a cycle"]'::jsonb, 3, 'Each draw has a lead-time demand of 20, which is 0.500000 above 19.5, so all 50 draws run short and the reason reads 50 of 50 draws above the reorder point 19.5: a stockout probability of 1 a cycle. The engine rounds no reorder point, splits no draws, and accepts any stated point at or above 0.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 3, 'Which reading does the engine state for a lead-time demand exactly equal to the reorder point, and what alternative does it name?', '["It is met; the alternative counts equality as a stockout", "It is a stockout; the alternative counts equality as met", "It counts half a stockout; the alternative counts a whole one", "It is met for whole units; a fraction counts as a stockout"]'::jsonb, 0, 'The engine''s reading is that a lead-time demand equal to the reorder point is met, and the alternative it names counts equality as a stockout. On constant inputs the choice is the whole answer, 0 against 1; with sampled inputs a draw almost never lands exactly on the point. No half counting or special rule for fractions exists.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 4, 'When a cycle service level is stated, how does the engine find the reorder point for it among the sampled lead-time demands?', '["It adds k times the sampled standard deviation to the sampled mean of the lead-time demand, with k from the inverse normal", "It reads the P90 of the lead-time demand, the figure that is met or exceeded in 90 percent of all the draws it made", "It sorts the draws and reads the one at index ceil(level x draws) - 1, the smallest that at least that share of draws does not exceed", "It raises the stated reorder point one unit at a time until the counted stockouts fall below the share the target allows"]'::jsonb, 2, 'The engine reads the sorted lead-time demand at index ceil(0.95 x n) - 1 for a level of 0.95: the smallest draw that at least 95 percent of draws do not exceed. A mean plus k sigma is the normal safety stock of the Professional tier; the P90 is the low figure; the engine searches no stated point unit by unit.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 5, 'Which reorder point would meet a cycle service level of 0.95 for the mechanical seal, as the engine estimates it on seed 20270301 and 20000 draws?', '["Exactly 3 seals, since the stated point was set to meet 0.95 and achieves it on these same draws", "An estimate of 2.780743 seals, the P10, while the stated 3 achieves a cycle service of 0.95 exactly", "An estimate of 3.062282 seals, while the stated 3 achieves a sampled cycle service of 0.941400", "An estimate of 1.986608 seals, the mean, while the stated 3 achieves 0.058600 of service"]'::jsonb, 2, 'On that seed and draw count the sorted draw for 0.95 is 3.062282 seals, and the stated point of 3 gives a sampled cycle service of 0.941400: just short of the target. Both are estimates and neither is graded. 2.780743 is the P10 and 1.986608 the mean of the lead-time demand; 0.058600 is the stockout probability.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 6, 'The reorder point for a cycle service level is the engine''s stated reading at one sorted index, and the course runs it on the seal on seeds 20270301 and 20270302. What alternative does the engine name for it?', '["One sorted draw higher, a difference of one draw that lies well inside the noise of these two seeds", "Taking the mean of the two sorted draws either side of the index, at the exact halfway point", "The same index read on the demand draws alone, with the lead time held fixed at its stated mode", "The largest draw of the run, so that no cycle at all in the sample runs out of stock"]'::jsonb, 0, 'The engine''s words are reorderPointForService is the sorted lead-time demand at index ceil(0.95 x n) - 1, and the alternative it names is one sorted draw higher. No averaging, no fixed lead time and no maximum enters either reading; the course states the reading so a learner can reproduce the figure exactly.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 7, 'A lead-time risk call on the seal states no cycle service level. What happens to the reorder point for a cycle service level?', '["The call is refused, since serviceLevel is a required input of every lead-time risk call", "It is read at a cycle service level of 0.95, the level the Ekene case happens to state", "It is set to the stated reorder point of 3, and the stockout count is left out of the result", "It comes back as none, and the service line of the basis says: no serviceLevel stated"]'::jsonb, 3, 'The cycle service level is the one optional input of the call: left out, the reorder point for a cycle service level is none and the basis says no serviceLevel stated, while the stockout count on the stated reorder point of 3 is unchanged. Nothing is refused, no level is borrowed, and the count is still returned.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 8, 'What does the engine return when a lead-time risk call states a cycle service level of 1?', '["the largest sampled lead-time demand, the only point that no draw exceeds", "serviceLevel must be a number strictly between 0 and 1; got 1", "serviceLevel must be a number from 0 to 1; got 1", "a reorder point of none, as if no cycle service level had been stated"]'::jsonb, 1, 'A cycle service level of 1 would need a point above every possible draw, and the engine refuses it by name; the keyed message is its own words. It returns no maximum and no none on a refused input, and the range it states is strict at both ends.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 9, 'Can a reorder point of -1 be stated for the seal, and what comes back?', '["reorderPoint must be a finite number at or above 0; got -1, because a reorder point counts seals held on the shelf when the next order goes out", "reorderPoint must be a finite number above 0; got -1, as a reorder point of 0 would hold no stock and so leave every cycle short", "a result in which every draw with any demand counts as a stockout, since no stock is held against the demand over the lead time", "a result with the reorder point read as 0, the lowest stock there can be on the shelf, and the run then sampled as usual"]'::jsonb, 0, 'A reorder point is stock on hand and cannot be negative, so the engine refuses -1; the keyed message is its own words. A reorder point of 0 is accepted (at or above 0), so a message asking for a figure above 0 is not the engine''s. On 0 any draw with demand is a stockout, but -1 returns no result and is never clipped to 0.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 10, 'A case holds the demand constant at 1.5 a day and samples the lead time, 5000 draws on seed 42. How does the engine''s sampling line mark the constant?', '["per iteration a uniform for the lead time only; the demand rate is fixed once in the header", "per iteration a uniform for the demand rate (constant: 1.5) then one for the lead time", "per iteration a uniform for the lead time then one for the demand rate (constant: no draw)", "per iteration two uniforms, the second one discarded because the demand rate is fixed"]'::jsonb, 2, 'The basis keeps the stated order and names the constant: per iteration a uniform for the lead time then one for the demand rate (constant: no draw). A constant spends no uniform, and nothing is drawn and thrown away; the lead time still comes first and the constant is marked in place.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 11, 'A lead-time risk call samples a demand of 1, 2 and 4 a day and a lead time of 5, 10 and 20 days (each a triangle: minimum, mode, maximum) and runs exactly one draw on seed 0. What does the engine print for the sampled lead-time demand''s P90 and P10?', '["9.768001 for the P90 and none for the P10, which needs ten draws", "a refusal, since one draw cannot be sorted into any percentiles", "the triangle''s minimum for the P90 and its maximum for the P10", "9.768001 for both, since that one draw is every percentile"]'::jsonb, 3, 'With a single draw the sorted list has one value, so the P90, P10 and every other figure are that one sampled draw: 9.768001 (engine, seed 0, one draw), and one draw leaves no spread to read. The draw count runs from 1, so one draw is accepted; no percentile is left empty; the triangle''s ends are no draws.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 12, 'At the stated reorder point of 3, what share of the seal''s cycles runs without a stockout, estimated on seed 20270301 and 20000 draws?', '["0.950000, the stated target, which the engine returns for any stated point", "0.941400, an estimate: one less the sampled stockout probability of 0.058600", "0.058600, the share of the draws that the stated reorder point of 3 covers fully", "0.969295, the service a reorder point held up to a whole seal achieves"]'::jsonb, 1, 'The cycle service level is the share of draws with no stockout, one less 0.058600: 0.941400 on that seed and those draws, an estimate that is not graded. 0.95 is the stated target for the reorder point for a cycle service level; 0.058600 is the stockout probability itself; 0.969295 is a Professional figure for the choke beans.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 13, 'The engine holds one demand rate for a whole lead time. What does the lesson teach that stated choice does to the sampled lead-time demand?', '["A high rate is never offset by a quiet day within the same lead time, so a busy spell stays busy until the order lands", "A fresh rate for each day would widen the spread of the lead-time demand, so holding one rate for the whole lead time narrows it", "It makes the lead-time demand equal the mean demand over the lead time in every single draw of the whole run", "It lets the busy days and the quiet days offset each other within each lead time drawn, as a daily draw would do"]'::jsonb, 0, 'The lesson teaches it as the engine''s stated choice: one rate a lead time means a busy spell stays busy until the order lands, so extreme lead-time demands stay in. A fresh draw every day is the alternative the engine names, under which quiet days could offset busy ones; the course states the reading and grades no figure on it. The demand still varies from draw to draw.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 14, 'The seal could also be stocked with the normal safety stock of the Professional tier. What does the lead-time Monte Carlo keep that a normal curve would lose?', '["The stated seed of the normal run", "A fill rate for the seal as its target", "Each graded reorder point of the case", "The skew of the stated triangles"]'::jsonb, 3, 'The Monte Carlo reads the stated triangles directly, and both lean right, so it keeps their skew; a normal curve is symmetric. The normal safety stock is closed form and takes no seed; a fill rate is a target either tool may be given; nothing sampled is graded.'),
  ('materials', 'advanced', 'module', 'm04-stockouts-and-the-reorder-point', 15, 'The seal''s reason prints "a stockout probability of 0.0586 a cycle" while the field reads 0.058600. Why the difference?', '["The reason is rounded to four decimals, while the field keeps all six decimals of the estimate", "Two samples differ: the field is computed on 20000 draws and the reason on the first 2000", "Inside a message a computed probability prints to six decimals with its trailing zeros dropped", "The reason prints a percentage in place of a probability, and the field a fraction"]'::jsonb, 2, 'The print rule inside a message is money to the cent and a computed quantity, factor or probability to six decimal places with trailing zeros dropped, so 0.058600 prints as 0.0586. Both come from the same 20000 draws on seed 20270301; neither is a percentage; no four-decimal rounding is applied.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 1, 'Three criticality weights of 33.3, 33.3 and 33.4 with a score of 7 out of 10 on each give a sum the computer holds a hair below 70. Against a V minimum of 70, what class does the engine return, and by which stated reading?', '["The class below V: the stored sum sits under 70, and the engine compares the doubles exactly", "Class V: the engine rounds every weighted score to a whole number before any comparison", "Class V: two figures that agree to 12 significant digits tie, so the sum meets the minimum", "No class: the weights add to 100 only approximately, so the criteria are refused by name"]'::jsonb, 2, 'Compared at 12 significant digits, the stored sum reads as 70 and meets the V minimum; the engine''s reason is T: weighted score 70 is at or above 70, the minimum for class V. Exact comparison of the doubles is the alternative it names; it rounds no score to a whole number; the weights pass within the stated tolerance of 1e-9.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 2, 'Under an all-units schedule two candidates, 100 and 200, both cost 200.000000 a year. What does the engine order, in its own words?', '["order 100 at a total cost of 200 a year (band 0), the lowest of 2 candidates; tied on cost, the smaller quantity is taken", "order 200 at a total cost of 200 a year (band 1), the lowest of 2 candidates; tied on cost, the larger quantity is taken", "order 150 at a total cost of 200 a year, the mean of 2 tied candidates, rounded by the stated rule", "breaks must offer a single cheapest candidate; 2 candidates tie at a total cost of 200 a year"]'::jsonb, 0, 'The engine''s stated reading takes the smaller quantity when two totals agree to 12 significant digits; the keyed reason is verbatim. The larger quantity is the alternative it names, which it does not take; it never averages candidates, and a tie is a result with a reason; it is no refusal.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 3, 'In a stated case built to tie on cost, 0 spares and 1 spare both total 365000.000000 a year. Which stock does the engine keep?', '["1 spare: the stated reading takes more spares on any tie, so that a failure never has to wait for its first spare", "0 spares: the stated reading takes fewer spares on a tie, and the reason shows the first spare adds and saves 230724", "2 spares: the engine breaks the tie by taking the largest number of spares searched", "Neither: the engine refuses a search whose two cheapest totals agree to 12 digits"]'::jsonb, 1, 'A spares tie takes fewer spares, the engine''s stated reading; its reason reads 0 spares: holding 0 a year against expected downtime 365000, total 365000, the lowest for 0 to 2; one more spare adds 230724 of holding and saves 230724 of downtime. More spares is the alternative it names; two spares cost more; a tie is no refusal.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 4, 'Items a and b each carry an annual usage value of 10.000000. How does the engine rank them, and what alternative does it name?', '["b at rank 1 and a at rank 2, ties by id descending; the alternative is id ascending", "both at rank 1, sharing the rank; the alternative gives them the ranks 1 and 2", "whichever was listed first, at rank 1; the alternative ranks them by unit cost", "a at rank 1 and b at rank 2, ties by id ascending; the alternative is id descending"]'::jsonb, 3, 'The engine''s words are ranked highest first (ties by id), ascending: a rank 1, b rank 2. Descending by id is the alternative it names. It gives no shared ranks, and it ranks by neither the order of listing nor unit cost; where tied items straddle a cut-off, the rank decides the class.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 5, 'A Poisson cycle-service target is stated as exactly the cumulative probability at level 1 with a mean of 1, to every digit the computer holds. Then it is raised to 0.7358. What levels does the engine return?', '["Level 2 for the exact target, and level 2 for 0.7358", "Level 1 for the exact target, and level 1 for 0.7358", "Level 0 for the exact target, and level 1 for 0.7358", "Level 1 for the exact target, and level 2 for 0.7358"]'::jsonb, 3, 'A Poisson cycle-service target is met at or above it, the engine''s stated reading: F(1) = 0.735759 meets the exact target, so the level is 1; 0.7358 is just above F(1), so the next level, 2, where F(2) = 0.919699. Met only strictly above is the alternative, which would move the exact case to 2; level 0 has F(0) = 0.367879.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 6, 'An EOQ of exactly 50.000000 is rounded to the nearest multiple of 100. What does the engine order, and which stated reading acts?', '["0.000000: the nearest multiple takes halves downward", "100.000000: the nearest multiple takes halves upward", "50.000000: a figure halfway between multiples stays put", "a refusal: a halfway figure has no single nearest multiple"]'::jsonb, 1, 'The engine''s reason is EOQ = sqrt(2 x 25 x 50 / 1) = 50; ordered as 100 (the nearest multiple of 100 (halves upward)), a relevant cost of 62.5 a year against 50 at the EOQ. Halves downward is the alternative it names, and here it would order nothing, which the engine refuses as a rule that orders nothing. No figure stays unrounded under a stated rule.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 7, 'Which pair of slow-moving edges does the engine apply, reading at the stated bands and a cover limit of 24 months?', '["An item at exactly 12 months is slow, and exactly 24 months of cover is inside the limit", "An item at exactly 12 months is still active, and exactly 24 months of cover is excess", "An item at 11.99 months is slow, and 25 months of cover is still inside the limit", "An item at exactly 12 months is slow, and exactly 24 months of cover is excess"]'::jsonb, 0, 'A band minimum is reached at or above it, and excess is stock strictly above the cover limit: AT12 is slow, BELOW12 at 11.99 is active, COVER24 is inside and COVER25 is one unit excess. Each edge is the engine''s stated reading, with reached only strictly above and at or above the limit as the alternatives it names.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 8, 'At a demand rate of 5 a period, a Poisson call with a lead time of 100 gives a mean of exactly 500. What happens there, and at a lead time of 100.5?', '["At 100 the call is refused, since the mean must be below 500; at 100.5 the normal safety stock is computed", "Both are accepted, since the cap limits the level the engine returns and leaves the mean free", "At 100 the call is accepted with a level of 500; at 100.5 it is refused, since the mean would pass the cap of 500", "Both are refused, since any Poisson mean of 500 or more is handed to the normal safety stock"]'::jsonb, 2, 'The mean may reach 500 and no more: a mean of exactly 500 returns level 500, and a lead time of 100.5 is refused in the engine''s words, leadTime must be at most 100 so that the mean demand demandRate x leadTime is at most 500; above that the normal safetyStock serves; got 100.5. The engine never switches to the normal method on its own.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 9, 'At a demand of 3 a period a Poisson lead time of 170 is refused with a largest accepted value of 166.666666. What happens when that printed figure is typed back?', '["It is refused again, since 166.666666 times 3 still falls short of the exact cap of 500 that the engine holds", "It is accepted and returns a level of 500, since the printed limit was rounded toward the accepted side", "It is refused again, since the engine asks for the limit to more decimals than it printed", "It is accepted, and the engine answers with the normal safety stock above a mean of 500"]'::jsonb, 1, 'Where the largest accepted value has more than six decimals the engine prints it rounded down at the sixth decimal so that it is accepted, and says so; typed back, 166.666666 gives level 500. A figure below the cap is within it; the engine asks for no more decimals; it computes no normal stock inside a Poisson call.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 10, 'Caplice lecture 11 slide 24 prints a safety stock of 348 at an item fill rate of 0.95. What does the engine''s fill-rate rule give on the same inputs?', '["348, the printed figure, since the slide is a published check", "424.518354, the cycle-service safety stock that sits at 0.95 on that slide", "423.000000, the figure the two-decimal table reading of the slide gives", "339.179604, 8.820396 below the print, with a safety factor of 1.314197"]'::jsonb, 3, 'The fill-rate rule gives a safety factor of 1.314197 and a safety stock of 339.179604 (engine), 8.820396 below the print; at that stock the achieved fill rate is 0.950000. The other three rows of that column agree to within 2 units, so 348 is a slip, and the engine keeps its rule. 424.518354 and 423.000000 belong to the cycle-service column.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 11, 'Caplice lecture 13 slide 12 prints the expected units short beyond level 4 as 0.009. What does the recursion the same slide states give?', '["0.001619: the loss at level 3, 0.010699, less one less 0.990920", "0.009: the recursion and the print agree at the precision printed", "0.010699: the loss at level 3, which the print carries one row down", "0.007669: the probability at level 4 that the print reads in its place"]'::jsonb, 0, 'L(4) = L(3) - (1 - F(3)) = 0.010699 less one less 0.990920, which gives 0.001619 (engine), and the printed 0.009 is the recursion''s figure at no precision the slide uses: a slip. 0.010699 is the loss at level 3 and 0.007669 is the probability at level 4; neither is the loss at level 4.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 12, 'MIL-HDBK-338B prints 0.986 for the lamps where the engine gives 0.985612. How does the course read that difference?', '["A slip in the handbook, which the course lists with the lecture slips", "An error in the engine, which should return 0.986 to match the print", "The same figure at three decimals, a rounding and no slip", "A different mean, since the handbook reads its failure rate per day"]'::jsonb, 2, '0.985612 rounds to 0.986 at three decimals, so the handbook''s figure is the engine''s printed at lower precision: a rounding, and no slip. The two slips the course names are both in the MIT lectures; the engine never changes a rule to match a print; the handbook''s rate is 0.001 failures per hour, and the mean is 0.500000 either way.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 13, 'Harris (1913) prints his first lot as 2,190. What does the engine return on his figures, and how does the course read the print?', '["2,190 exactly: the engine rounds down to the printed lot so that the published check passes as printed", "2190.890230: the print is a slip in Harris''s arithmetic, which the course lists beside the two lecture slips", "6856.626965: the engine reads his first example with the connector figures of his Figure II", "2190.890230: Harris prints each lot short of the formula''s figure, and the engine keeps the rule"]'::jsonb, 3, 'The engine''s EOQ on his first example is 2190.890230, and Harris prints 2,190: he prints each of his lots short of the formula''s figure. The course calls that a habit of printing and no slip, and the engine never bends its rule to match. 6856.626965 is the EOQ of his Figure II connector, a different lot.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 14, 'What does the course say about the capstone fields and the readings the engine states?', '["Every capstone field is the same number under each reading and under the alternative the engine names", "Each capstone field is graded under the engine''s readings, which the course treats as the law of the subject", "The capstone fields change under the alternatives, and the tolerance is widened so that it covers both", "The capstones grade the readings directly, with one field for each tie and each boundary"]'::jsonb, 0, 'No graded figure depends on a reading: the course proves, field by field, that each is the same under every reading and its alternative. The readings are stated choices and are never presented as the law, no tolerance is widened, and no field grades a tie or an edge.'),
  ('materials', 'advanced', 'module', 'm05-readings-ties-and-boundaries', 15, 'Why do some of the engine''s edges include the boundary and others exclude it?', '["Every edge includes the boundary, and a strict edge appears only where a figure is rounded by a stated rule", "Each rule states its own edge in its own words (at or above, at or below, above), and none is global", "An edge is inclusive where the stated figure is a target to meet, and strict where it is a limit to pass", "The edge follows the tier: Associate rules include the boundary and Expert rules exclude it"]'::jsonb, 1, 'No single principle sorts the edges; each rule states its own. A class minimum and a band''s starting month are met at or above. Under at-or-below an ABC cut-off is a limit, yet a cumulative share exactly on 80 stays A, and a Poisson fill-rate level is met when its expected units short are at or below what the target allows, so a limit can be inclusive. Excess cover counts only above its limit, and a lead-time demand equal to the reorder point is met. The engine prints those words in its reasons; no edge depends on rounding or on the tier.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 1, 'The ESP motor''s 2 failures a year enter the insurance call as a stated number. Where does estimating a failure rate from field data belong?', '["To the rotating course and the reliability parts of the academy; this engine takes the rate as stated", "To this engine, which fits the rate from the months since the last issue in the register", "To the uncertainty course, which samples the rate on the seed that the spares calculator states for each run", "To the procurement course, which reads the rate from the supplier''s tender for the motor"]'::jsonb, 0, 'The engine estimates no failure rate from field data; it takes a stated failure rate a year, and the rotating course and the reliability parts of the academy own the estimate. The register''s months since the last issue feed the slow-moving bands only; the uncertainty course owns Monte Carlo as a subject; procurement owns tendering.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 2, 'How does the engine handle the time value of money in the ESP motor''s cheapest stock of 4 spares at 160003.732064 a year?', '["It discounts each year a spare sits on the shelf at the holding rate of 0.2 and reports the NPV of the whole stock", "It discounts the downtime cost at a rate it holds itself, so the total is a present value", "It discounts nothing: the cost is in money of one year, and discounting and NPV belong to the cash flow course", "It computes the NPV through the canonical cash flow engine and prints it beside the total"]'::jsonb, 2, 'No figure in the engine is discounted and no NPV is computed; the insurance total is a cost a year, and the cash flow course owns discounting. The holding rate is a charge a year on the unit cost; the engine holds no rate of its own; it imports only lib/stats, the percentile convention and the incomplete gamma.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 3, 'The CSG-958 casing is costed on a stated price schedule. Which course owns how that schedule was tendered and evaluated?', '["This engine, which scores each bid received and keeps the price band with the lowest total cost", "The supply course, which sets terminal and depot stock and the prices that go with it at each depot", "The cash flow course, which discounts each band''s price to a present value first", "The procurement course; this engine takes the price schedule and discount type as stated"]'::jsonb, 3, 'Tendering, bid evaluation and contract types belong to Procurement, Tendering & Contracting; the engine takes a stated schedule and discount type. It evaluates no bids. The supply course owns terminal and depot stock; the cash flow course owns discounting, and nothing here is discounted.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 4, 'Where does a demand forecast come from in the engine''s calculations?', '["The register''s monthly usage, which the engine projects forward with a trend", "Nowhere in this course: the demand and its standard deviation are stated inputs", "From the uncertainty course''s Monte Carlo, run inside every safety stock call", "The months since the last issue, which the engine turns into a demand rate"]'::jsonb, 1, 'The engine forecasts no demand and fits no demand distribution: a stated demand and its standard deviation go in, and no course of this one owns a forecast. It projects no trend, runs no sampler inside a safety stock call, and uses the months since the last issue for the slow-moving bands alone.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 5, 'An insurance spares call on the ESP motor carries an extra key, holdingCost. What does the engine return?', '["a result that ignores holdingCost and uses the holding rate of 0.2 with the unit cost of 185000, as stated, and names the unread key in its reason", "holdingCost and holdingRate: state exactly one (holdingRate goes with unitCost), and the call stops there before any spares are priced", "holdingCost is not an accepted key; the accepted keys at the top level are failuresPerYear, leadTimeDays, daysPerYear, unitCost, holdingRate, downtimeCostPerDay, maxSpares", "a result that uses holdingCost in place of the holding rate, since a holding figure stated directly takes priority over a rate on the unit cost"]'::jsonb, 2, 'The engine reads no key it does not know: every function refuses an input key it does not read, naming the key, its path and the accepted keys, and the keyed message is verbatim. A misspelt or extra key is never dropped silently or used; the exactly-one message belongs to the eoq call, whose keys differ.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 6, 'The baryte EOQ case is sent with its rounding rule removed and an unknown key, roundTo, added. Which refusal comes back first?', '["the refusal of roundTo as an unknown key, since the accepted keys are checked before any input is read", "the refusal of the missing rounding rule, since each function reads its stated rules before its other keys", "both refusals, joined in one message that names roundTo first and rounding second", "a result at the EOQ of 137.408584, with roundTo read as a rounding rule of none"]'::jsonb, 0, 'Every function checks its accepted keys before it reads an input, so the unknown key is refused first, in the engine''s words roundTo is not an accepted key; the accepted keys at the top level are annualDemand, orderCost, holdingCostPerUnitYear, unitCost, holdingRate, rounding. The missing rounding rule would be refused next, but a call stops at its first refusal; the engine joins no messages, and an unknown key is read as no rule.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 7, 'An ABC call carries 5001 items. What does the engine say, and what happens at exactly 5000?', '["items has 5001 entries; the cap is 5000, and a call of exactly 5000 items is refused as well", "items has 5001 entries; the cap is 5000, and a call of 5000 items is accepted and ranked", "a result on the first 5000 items, with the last one dropped and then named in the reason", "a result on all 5001 items, since the cap only applies to the criticality and slow-moving calls"]'::jsonb, 1, 'MAX_ITEMS is 5000 for one criticality, ABC or slow-moving call; 5001 is refused by name with the cap in the message, and 5000 is accepted. The engine drops no item and truncates no list; the cap applies to all three of those functions.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 8, 'An insurance call puts seven hundred failures a year on the motor, with a replacement that takes a whole year (365 days, in a year of 365 days), pushing the mean orders outstanding past 500. What does the engine return?', '["leadTimeDays must be at most 365 so that the mean number of orders outstanding is at most 500; got 365, the whole year stated as the lead time", "maxSpares must be a whole number from 0 to 1000; got 6, since a mean above 500 orders outstanding needs a far larger search limit than 6", "a result with 6 spares at the search limit, flagged so that a larger stock may cost less, since a mean above 500 lies far beyond the limit of 6", "leadTimeDays must be at most 260.714285 (rounded down at the sixth decimal so that it is accepted) so that the mean number of orders outstanding is at most 500; got 365"]'::jsonb, 3, 'The mean orders outstanding may not pass 500, and the engine refuses the lead time that pushes it over, printing the largest accepted value rounded toward the accepted side; the keyed message is its own words. It names the lead time and leaves the stated failure rate as it is, prints the limit to six decimals rounded down, refuses before any search, and accepts the stated maxSpares of 6.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 9, 'Which figures does the engine hold of its own, with no input stating them?', '["Only the 12 in DEFAULTS: its tie convention, the weight sum and its tolerance, and its caps", "The 12 in DEFAULTS and a standard holding rate that applies whenever no holding rate is typed", "Its caps and a cycle service level of 0.95, applied whenever a service level is left out", "Its caps and the Ekene policy''s bands, which apply whenever no slow-moving band is stated"]'::jsonb, 0, 'Every cost, rate, cycle service level or fill rate, band and seed is a stated input with no default; the only figures the engine holds are the 12 in DEFAULTS, from TIE_DIGITS 12 to MAX_SPARES 1000. A missing holding rate, service target or band is refused by name, and the Ekene policy is a stated case; it is no fallback.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 10, 'Which alternative does the course name beside the engine''s one-for-one insurance convention?', '["One demand rate held for the whole of each sampled lead time drawn", "A holding charge that carries interest on the set-up cost as well", "A spread on the review period as well as a spread on the lead time", "A repair loop, partial loss, or holding on spares in stock only"]'::jsonb, 3, 'The insurance convention is the one-for-one pipeline, one unit down a waiting failure, with holding on every spare bought; its alternative is a repair loop, partial loss, or holding on spares in stock only. One rate a lead time is the lead-time risk choice itself; interest on the set-up cost is the Harris alternative to the holding cost; a review-period spread is the lead-time spread alternative.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 11, 'The ESP motor''s reason prints a total of 160003.73 while the tile reads 160003.732064. Which convention is at work?', '["The rounding rule: the stated nearest multiple of 0.01 is applied to the total cost", "The tie rule: two totals that agree to 12 significant digits print only to the cent", "The print rule: money to the cent inside a message, and the field at six decimals", "The holding rule: the holding charge is billed to the cent on each spare that is bought"]'::jsonb, 2, 'Inside a message the engine prints money rounded to the cent and a computed figure to six decimals; the field keeps its full value, which the tile shows at six decimals. No rounding rule applies to an insurance total, and neither the tie rule nor the holding charge sets how a figure prints.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 12, 'Which convention of the engine does Harris (1913) write differently, as the course states it?', '["The rounding rule: Harris rounds every lot to the nearest multiple of ten units in his tables", "The holding cost: Harris lets the carrying charge also carry interest on the set-up cost", "The ties: Harris compares his lot costs exactly, and the engine at 12 digits", "The lead-time spread: Harris lets the review period vary as well as the lead time of each order"]'::jsonb, 1, 'The engine charges holding on the units held, stated directly or as a rate on the unit cost; the alternative the course names is a holding charge that also carries interest on the set-up cost, as Harris 1913 writes it. Harris rounds his stud to 49 with a stated say, sets no ties rule, and treats no lead-time spread.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 13, 'A written stock policy names each insurance spare''s inputs. Which list is complete?', '["The failure rate, lead time, unit cost and downtime cost, the four figures that move the answer most", "The failure rate, lead time and days a year, since all of the costs follow from the register itself", "The unit cost, holding rate and downtime cost, since the failure rate is a reliability figure elsewhere", "The failure rate, lead time, days a year, unit cost, holding rate, downtime cost and search limit"]'::jsonb, 3, 'For each insurance spare the policy names the failure rate, lead time, days a year, unit cost, holding rate, downtime cost and search limit, every input of the call. Each shorter list leaves out a stated input the engine refuses without; the register states no holding rate or downtime cost, and a stated failure rate stays in the policy whoever estimated it.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 14, 'How does a written stock policy record a figure from the lead-time Monte Carlo?', '["With its seed and its draws, as an estimate kept apart from every graded figure", "As the P90 alone, since the platform''s one convention makes the seed needless", "Rounded to a whole unit, since a sampled figure is exact only to the nearest unit", "As the mean of three runs on three seeds, which removes the need to state any seed"]'::jsonb, 0, 'The policy names each sampled figure with its seed and draws, and the course calls it an estimate and grades none. The P-label convention sets how a percentile is labelled and says nothing of how a run is reproduced; the engine rounds no sampled figure; averaging seeds still needs each seed stated.'),
  ('materials', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 15, 'Which description fits every graded number in this course?', '["A figure the learner reads off the Monte Carlo view, quoted with its seed and draws", "Any figure printed in a published source, which the engine was set up to reproduce exactly as printed", "A return value of the engine on fixed inputs, so there is exactly one right answer on any machine", "A figure under the engine''s stated readings, which the capstone then treats as the law of the subject"]'::jsonb, 2, 'Every graded number is a return value of the engine on inputs written down in advance; no graded figure is a Monte Carlo draw, and none depends on a reading. A published print can be a slip, as two of them are, and the engine keeps its rule.'),
  ('materials', 'advanced', 'final', null, 1, 'A planner doubles the ESP motor''s lead time while keeping every other input. By what factor does the engine''s mean number of orders outstanding move?', '["It stays put, since the lead time enters the costs and leaves the mean alone", "It doubles, since the mean is proportional to the lead time in days", "It rises by the square root of two, as an economic order quantity would", "It halves, since a longer lead time spreads the same failures more thinly"]'::jsonb, 1, 'The mean is failuresPerYear x leadTimeDays / daysPerYear, so it moves in proportion to the lead time, as it does to the failures a year. The square root belongs to the EOQ, where the lot grows with the square root of demand; a longer lead time keeps more orders on their way and cannot keep fewer.'),
  ('materials', 'advanced', 'final', null, 2, 'Which two stated inputs together make up the holding step that each extra ESP motor spare adds to the yearly total?', '["The downtime cost of 18000 a day and the 365 days a year", "The unit cost of 185000 and the holding rate of 0.2", "The unit cost of 185000 and the 2 failures a year", "The holding rate of 0.2 and the lead time of 150 days"]'::jsonb, 1, 'Each spare bought carries unitCost x holdingRate a year, 37000.000000 on the motor. The downtime cost a day and the days a year price the units down; the failures a year and the lead time set the Poisson mean, and neither enters the holding charge.'),
  ('materials', 'advanced', 'final', null, 3, 'In the ESP motor table, which two figures add up to the three-spare total of 188347.405085 a year?', '["148000.000000 of holding and 12003.732064 of downtime", "111000.000000 of holding and 409957.821135 of downtime", "74000.000000 of holding and 77347.405085 of downtime", "111000.000000 of holding and 77347.405085 of downtime"]'::jsonb, 3, 'Three spares carry 3 times 37000.000000 of holding, 111000.000000, and 77347.405085 of downtime, which add to 188347.405085 (engine). The pair 148000.000000 and 12003.732064 totals the cheapest stock of four; 409957.821135 is what two spares leave in downtime; 74000.000000 is what two spares cost to hold.'),
  ('materials', 'advanced', 'final', null, 4, 'Reading down the ESP motor table, by how much does the yearly downtime fall when a fifth spare is added to four?', '["By 37000.000000, exactly the holding it adds, so four and five tie on cost, as the table shows", "By 12003.732064, the whole downtime cost left over at four spares", "By 10425.849112, well short of the 37000.000000 the fifth spare adds in holding", "By 1577.882952, the downtime cost that is still left once five spares are held on the shelf"]'::jsonb, 2, 'From four spares to five the downtime falls from 12003.732064 to 1577.882952, a saving of 10425.849112 a year, while holding rises by 37000.000000, so four stays cheapest. No tie arises; 12003.732064 is the downtime at four spares, and only part of it is saved.'),
  ('materials', 'advanced', 'final', null, 5, 'The motor''s four-spare no-shortage figure and its five-spare fill rate print identically, 0.998413. Why?', '["Coincidence of the stated inputs: another failure rate or lead time would pull the two figures apart", "Rounding at six decimals hides a gap further out, so the course keeps the two figures apart as different", "The rule makes the second the first: a failure finds a spare when fewer than five orders are outstanding", "The search stopped at 6, and figures near the search limit are copied from the row above them"]'::jsonb, 2, 'A failure finds one of five spares when four or fewer orders are outstanding, which is exactly the chance of no shortage with four. The engine returns them equal by construction, so here printed alike is equal because the rule says so; no input, rounding or search limit enters.'),
  ('materials', 'advanced', 'final', null, 6, 'Why does the course quote MIL-HDBK-338B word for word, while it cites the MIT lectures only by lecture and slide?', '["The handbook is newer than the lectures, and the course quotes only the newest of its sources", "The lectures print no figures of their own, so there is nothing in them to quote", "The handbook is public domain; the lectures are CC BY-NC-SA 4.0 and this course is sold", "The handbook''s authors asked to be quoted, and the lectures'' author did not"]'::jsonb, 2, 'Only public-domain texts are quoted, with their citation: Harris 1913 and MIL-HDBK-338B. The lectures are licensed for non-commercial use, and this course is sold, so their figures are cited by lecture and slide and their ideas taught in the course''s own words. The lectures do print figures, which the course cites.'),
  ('materials', 'advanced', 'final', null, 7, 'A downtime cost of 100 a day on the ESP motor moves the cheapest stock from four spares to none. What made the difference?', '["Only the price of waiting moved: the first spare now saves 20455.05 of downtime against 37000 of holding", "The mean orders outstanding fell below one half, so no spare is likely to be needed in any lead time", "A higher holding rate came with the lower downtime cost, which the engine links to it by a stated rule", "The search limit fell to 0, since cheap downtime shortens the search for spares down to an empty stock"]'::jsonb, 0, 'At 100 a day the failure rate, lead time and mean are unchanged, and only the downtime price moved; the engine''s reason shows the first spare adding 37000 of holding and saving 20455.05 of downtime, so none is cheapest. The engine links no input to another, and the stated search limit of 6 is unchanged.'),
  ('materials', 'advanced', 'final', null, 8, 'With a holding rate of 0 and a search limit of 3 on the ESP motor, why does the engine flag its answer?', '["A holding rate of 0 is refused, and the flag marks the refusal on the search limit", "Three spares is the first row where the fill rate passes 0.99, and the flag marks that target", "The downtime saved by the third spare ties the holding it adds, and ties are flagged", "Every spare is then free to hold and saves some downtime, so the largest number searched wins"]'::jsonb, 3, 'With free holding each extra spare lowers the total, so the cheapest found is always the last row, and the engine says: 3 spares: holding 0 a year against expected downtime 77347.41, total 77347.41, the lowest for 0 to 3; the search stopped at maxSpares 3, so a larger stock may cost less. A rate of 0 is accepted; the engine aims at no fill rate; no tie arises.'),
  ('materials', 'advanced', 'final', null, 9, 'A planner asks the ESP motor case to search up to 1001 spares. What comes back?', '["A result at 1000 spares, the limit clipped to the cap and flagged at that edge", "A refusal naming the mean orders outstanding, whose cap is 500", "A refusal naming maxSpares, whose largest accepted value is the cap of 1000", "A result at 4 spares, since any search wide enough finds that stock"]'::jsonb, 2, 'The search limit may not pass MAX_SPARES, and the engine says so in its own words: maxSpares must be a whole number from 0 to 1000; got 1001. It clips no stated input and returns no result on a refused call; 500 caps the mean orders outstanding, a different refusal on the lead time.'),
  ('materials', 'advanced', 'final', null, 10, 'Reading down the ESP motor''s fill-rate column, which is the first stock whose fill rate is at or above 0.99, and how does it compare with the cheapest stock?', '["3 spares, with a fill rate of 0.990054; one spare fewer than the cheapest stock of 4", "5 spares, with a fill rate of 0.998413; one spare more than the cheapest stock of 4", "4 spares, with a fill rate of 0.990054; it is also the cheapest stock at the stated costs", "3 spares, with a no-shortage probability of 0.990054, which the column prints as its fill rate"]'::jsonb, 2, 'The fill rate with four spares is 0.990054, the first at or above 0.99; three spares give 0.949374. Four is also the cheapest stock, at 160003.732064 a year, although the engine aimed at no fill rate. 0.990054 is the no-shortage probability with three, a different column; five spares first reach 0.998413.'),
  ('materials', 'advanced', 'final', null, 11, 'On the mechanical seal, what are the two stated triangles the lead-time Monte Carlo draws from?', '["Lead time 70, 106.453303 and 160 days; demand a day 0.01, 0.016 and 0.03", "Lead time 70, 90 and 160 days; demand a day 0.01, 0.016 and 0.03 seals", "Lead time 83.198487, 103.503359 and 134.894691 days, the sampled percentiles", "Lead time 90 days held constant; demand a day 0.01, 0.016 and 0.03 seals"]'::jsonb, 1, 'The register states the seal''s lead time as a triangle of 70, 90 and 160 days and its demand a day as 0.01, 0.016 and 0.03. 106.453303 is the sampled mean, which is no stated mode; 83.198487, 103.503359 and 134.894691 are sampled P90, P50 and P10 figures; the lead time is a triangle, and a constant would be a different case.'),
  ('materials', 'advanced', 'final', null, 12, 'A planner types the seal''s lead time as the text 90 in place of a number or a triangle. What does the engine do?', '["It refuses leadTimeDays, which must be a number or a triangle of finite numbers", "It reads the text as the number 90 and runs the call on a constant lead time", "It ignores the lead time and samples the demand over a lead time of 0 days", "It refuses the whole call as options, which must be an object of named inputs"]'::jsonb, 0, 'The engine''s words for this probe are leadTimeDays must be a number or a triangular distribution { min, mode, max } of finite numbers. It converts no text into a number and drops no input; the options message is for a call handed something other than an object.'),
  ('materials', 'advanced', 'final', null, 13, 'Why is the seed a required input of every lead-time risk call?', '["So that the engine can grade the sampled figures against one fixed right answer", "So that every run can be reproduced: the same seed and draws give the same draws", "So that the seed can scale the triangles, which the engine stretches by its value", "So that the draw count can be read from it, since the seed fixes the number of draws"]'::jsonb, 1, 'The engine''s own refusal says why: seed must be a whole number from 0 to 4294967295; it is required so that every run can be reproduced. Reproducible draws still give an estimate, and no sampled figure is graded. The seed starts the mulberry32 stream only; the draw count is a separate stated input.'),
  ('materials', 'advanced', 'final', null, 14, 'On seed 20270301 and 20000 draws, the seal''s lead-time demand has a P90 of 1.306495 and a P10 of 2.780743 seals. Which is the low figure?', '["2.780743, the P10: met or exceeded in 10 percent of draws only", "1.306495, the P90: met or exceeded in 90 percent of the draws", "Neither: P90 and P10 name the same sorted draw read two ways", "1.907671, the P50: the low figure is always the median"]'::jsonb, 1, 'Sorted from small to large, the demand P90 is read at floor(0.1 n), so 1.306495 seals is the smaller of the two, exceeded by nine draws in ten; it is an estimate on that run and is not graded. 2.780743 is read at floor(0.9 n), the upper end where stock runs out; each label names its own sorted draw, and the median is the P50.'),
  ('materials', 'advanced', 'final', null, 15, 'A learner sees the seal''s reason "1172 of 20000 draws have a lead-time demand above the reorder point 3". How should the stockout probability be quoted?', '["As 0.058600 with no seed, since the reason already gives the draws it was made from", "As 0.0586 exactly, the seal''s true stockout probability a cycle at a reorder point of 3", "As 0.05, the figure the target of 0.95 implies for the seal on any seed at all", "As an estimate of 0.058600 on seed 20270301 and 20000 draws, which is not graded"]'::jsonb, 3, 'A sampled figure is quoted with its seed and its draws and called an estimate; the course writes the seal''s stockout probability as estimated at 0.058600 on seed 20270301 and 20000 draws. Without the seed it cannot be reproduced; no sampled figure is exact or true; the target implies nothing about what the draws return.'),
  ('materials', 'advanced', 'final', null, 16, 'A planner asks for 200001 draws on the seal. What happens?', '["The call runs on 200000 draws, the count clipped down to the cap, with a note in the basis", "The call runs all 200001 draws, since the cap is only a warning printed beside it", "The call is refused, since no more than 20000 draws are ever taken in one run", "The call is refused by name, since the draw count may not pass the cap of 200000"]'::jsonb, 3, 'MAX_ITERATIONS is 200000, and the engine refuses one more in its own words: iterations must be a whole number from 1 to 200000; got 200001. It clips no count and treats no cap as advice; 20000 is the draw count of the Ekene case, well inside the cap.'),
  ('materials', 'advanced', 'final', null, 17, 'A lead-time risk call misspells the mode of the seal''s lead time as mod. What comes back?', '["leadTimeDays must have min <= mode <= max; got min 70, mode undefined, max 160", "a result on the triangle 70, 90, 160, with the misspelt key read as the mode that it most closely resembles", "leadTimeDays.mod is not an accepted key; the accepted keys of leadTimeDays are min, mode, max", "a result with the lead time held at a constant 70 days, since no mode was stated"]'::jsonb, 2, 'An input key a function does not read is refused at whatever level it sits, with its path and the accepted keys, and the check comes before any other; the keyed message is verbatim. The engine guesses no key from its spelling, and it fills no missing mode.'),
  ('materials', 'advanced', 'final', null, 18, 'The constant case of 2 a day over 10 days is run twice, at reorder points of 20 and of 19.5. How do the two stockout probabilities compare?', '["0 at 20 and 1 at 19.5: equality is met, and half a unit short fails every draw", "1 at 20 and 1 at 19.5: equality counts as a stockout, so both points fail", "0 at 20 and 0.5 at 19.5: half a unit short fails half of the draws on the stated seed", "0 at both points: the engine rounds 19.5 up to 20 before it counts the draws"]'::jsonb, 0, 'Every draw is exactly 20: at a reorder point of 20 none is above it (0 of 50), and at 19.5 every draw is 0.500000 above it (50 of 50). Counting equality as a stockout is the alternative reading the engine names; the draws do not vary, so no half share arises; the engine rounds no stated point.'),
  ('materials', 'advanced', 'final', null, 19, 'The seal''s reorder point for a cycle service level of 0.95 is 3.062282 on seed 20270301 with 20000 draws, and 3.113782 on seed 20270302 with 2000 draws. How should a planner read the pair?', '["As two estimates of one quantity, each quoted with its seed and draws and neither graded", "As a contradiction, since a seeded sampler must return one reorder point on every run", "As proof that the second seed is faulty, since its figure sits further from the stated 3", "As two exact reorder points, of which the policy should keep the higher for safety"]'::jsonb, 0, 'Each figure is the sorted draw at ceil(0.95 x n) - 1 of its own run, and the course teaches that a sampled figure is an estimate that moves with its seed and draw count. A seed reproduces its own run, and no seed is faulty; neither figure is exact or graded.'),
  ('materials', 'advanced', 'final', null, 20, 'The inventory engine computes the standard normal cumulative probability without a normal table of its own. Through what?', '["A normal sampler in lib/stats, run on a fixed seed every time it is called", "A table read to two decimals, the way the lecture slides read their factors", "The percentile convention of lib/conventions/percentile.js, read backwards", "The regularised incomplete gamma, imported from engines/hse/safetyStats.js"]'::jsonb, 3, 'The engine imports regularizedGammaQ from engines/hse/safetyStats.js and computes Phi through it; its inverse is Wichura AS241. It samples nothing for Phi; a two-decimal table reading is a stated safety-factor rounding; the percentile convention supplies only the exceedance sentence.'),
  ('materials', 'advanced', 'final', null, 21, 'On the Ekene register, why is the PSV repair kit class V under the stated criticality policy?', '["It scores the maximum 5 on safety, which places it in class V whatever its weighted score of 68.000000", "Its weighted score of 68.000000 is at or above the V minimum of 70, compared at 12 digits", "It ranks in class A by annual usage value, and the policy lifts every class A item to V", "Its lead time is the longest on the register, and the policy puts the slowest items in V"]'::jsonb, 0, 'The stated override places an item scoring the maximum on safety in the first class: PSV-KIT: scores the maximum 5 on safety, which places an item in class V whatever its weighted score (68, class E by score alone). 68 is below 70 by any comparison; the kit is ABC class C; no lead-time rule exists.'),
  ('materials', 'advanced', 'final', null, 22, 'Under the Ekene ABC cut-offs of 80 and 95 percent, why is CEM-G class B under one boundary rule and class A under the other?', '["Its share is exactly 80 percent, which at-or-below places in A and include-crossing places in B", "The two rules rank the items in a different order, so CEM-G sits seventh under one and fifth under the other", "It crosses 80 percent: at-or-below reads its share with it, 83.536840, and include-crossing the share before, 78.753907", "Include-crossing rounds each cumulative share to a whole percent first, and 83.536840 rounds down to 80 there"]'::jsonb, 2, 'CEM-G''s cumulative share with it is 83.536840 and before it 78.753907. At-or-below decides on the share including the item, so B; include-crossing decides on the share before it, so the item crossing a cut-off joins A. The ranking is the same under both rules, and nothing is rounded.'),
  ('materials', 'advanced', 'final', null, 23, 'BARYTE''s EOQ is 137.408584 tonnes. Why does the register calculator order 140.000000?', '["The EOQ is always rounded to the nearest 10 tonnes, a fixed rule the engine holds", "140.000000 is the EOQ once the purchase cost of 78000.000000 a year enters the relevant cost of the order", "The holding cost is stated as 57.200000, which moves the optimum up to 140 tonnes", "The stated rule rounds up to a multiple of 10, and the order costs 0.017454 percent more than the EOQ"]'::jsonb, 3, 'The EOQ is the unrounded figure; the quantity ordered is the one the stated rounding rule gives, here up to a multiple of 10, at a relevant cost of 7861.142857 against 7859.770989, a penalty of 0.017454 percent. The engine holds no rounding rule; the purchase cost moves no EOQ; 57.200000 is the holding cost that gives 137.408584 itself.'),
  ('materials', 'advanced', 'final', null, 24, 'On the CSG-958 casing schedule, what does the engine order under all-units and under incremental discounts?', '["141.000000 at 365590.042553 under all-units; 120.000000 at 349720.000000 under incremental", "120.000000 under both types, since the break quantity of the cheapest band wins under either discount type", "77.000000 at 357689.090909 under both, since band 1 holds its EOQ under either type", "120.000000 at 349720.000000 a year under all-units; 141.000000 at 365590.042553 under incremental"]'::jsonb, 3, 'All-units prices the whole lot at the band''s price, so band 2''s break of 120 is the cheapest candidate at 349720.000000; incremental prices each unit by its own band, so band 2''s own EOQ, rounded to 141, costs 365590.042553 (engine). Swapping them reverses the two types; 77.000000 is the all-units band 1 candidate, which costs more.'),
  ('materials', 'advanced', 'final', null, 25, 'On the choke bean set, what safety factor does a cycle service level of 0.95 give, and what does a fill rate of 0.98 give?', '["1.644854 for the cycle service level of 0.95; 1.026327 for the fill rate of 0.98", "1.026327 for the cycle service level of 0.95; 1.644854 for the fill rate of 0.98", "1.644854 for both, since a service level of any kind sets k by the inverse normal", "1.959964 for the fill rate, the factor a cycle service level of 0.975 gives"]'::jsonb, 0, 'A cycle service level counts the cycles with any shortage and sets k = Phi^-1(0.95) = 1.644854; a fill rate counts units short against the order quantity of 12 and needs G(k) at or below 0.079222, so k = 1.026327 (engine). Swapping them confuses the measures; 1.959964 is the factor for a cycle service level of 0.975, no fill rate. A service level in this course always names its measure.'),
  ('materials', 'advanced', 'final', null, 26, 'Harris (1913) prints the lot for his stud as 48.5 and adds "or, say, 49". What does the engine order with the stated rule nearest multiple of 1?', '["49.000000, from an EOQ of 48.554321", "48.5, the lot that Harris prints", "48.554321, since the rule leaves it be", "50.000000, the next round lot up"]'::jsonb, 0, 'The EOQ on the stud''s figures is 48.554321, and the stated rule nearest multiple of 1 orders 49.000000 (engine), which matches Harris''s own "say, 49". Harris prints the lot short of the formula at 48.5; a stated rule always rounds; a nearest multiple of 1 gives 49.'),
  ('materials', 'advanced', 'final', null, 27, 'Which two printed figures does the course treat as slips in the texts it read?', '["0.986 in MIL-HDBK-338B''s lamp example, and 2,190 for Harris''s first lot", "601 at a cycle service level of 0.99 on lecture 11 slide 24, and 2835 on lecture 12 slide 6", "0.25 at level 1 on lecture 13 slide 12, and 400 on lecture 8 slide 9", "348 at a fill rate of 0.95 on lecture 11 slide 24, and 0.009 at level 4 on lecture 13 slide 12"]'::jsonb, 3, 'The two slips are the fill-rate safety stock of 348, where the rule gives 339.179604, and the loss of 0.009 at level 4, where the recursion gives 0.001619. The handbook''s 0.986 and Harris''s 2,190 are rounded prints; 601, 2835, 0.25 and 400 all agree with the engine at the precision printed.'),
  ('materials', 'advanced', 'final', null, 28, 'The PSV kits demand 0.5 a month over a lead time of 4 months, read as Poisson. What level does a cycle service level of 0.95 need, and why not 4?', '["Level 4, since P(X <= 4) of 0.947347 rounds to 0.95 at two decimals, which the engine counts as met", "Level 2, the Poisson mean, since the mean already covers the whole demand expected over the lead time", "Level 5, since P(X <= 4) is 0.947347 and falls short, while P(X <= 5) is 0.983436", "Level 3, since the expected units short at 3, 0.218018, is below 0.3"]'::jsonb, 2, 'The engine takes the smallest level whose cumulative probability meets the target: level 5: P(X <= 5) = 0.983436 is at or above 0.95; at 4 it is 0.947347 (Poisson mean 2). Nothing is rounded before the comparison; the mean alone carries no safety stock; level 3 is the answer to a fill rate of 0.95 with an order quantity of 6.'),
  ('materials', 'advanced', 'final', null, 29, 'At a fill rate of 0.95 with an order quantity of 6 kits, the PSV kits need level 3. What expected units short a cycle and achieved fill rate does the engine report there?', '["0.541341 units short a cycle, an achieved fill rate of 0.95", "0.218018 units short a cycle, an achieved fill rate of 0.857123", "0.218018 units short a cycle, an achieved fill rate of 0.963664", "0.075141 units short a cycle, an achieved fill rate of 0.983436"]'::jsonb, 2, 'At level 3 the loss is 0.218018, at or below 6 x (1 - 0.95) = 0.3, and the achieved fill rate is 0.963664 (engine). 0.541341 is the loss at level 2, which misses the target; 0.857123 is the cumulative probability at level 3, a cycle service figure; 0.075141 is the loss at level 4.'),
  ('materials', 'advanced', 'final', null, 30, 'Why does the engine refuse a Poisson call whose mean over the protection period would pass 500?', '["Above that mean the normal safety stock serves, and the cap is a stated figure the refusal names", "A Poisson table longer than 500 rows cannot be printed in the stock calculator at all, so it is cut there", "A mean of 500 is where the Poisson probabilities stop adding up to one inside the engine''s own arithmetic", "The cap is the largest demand the Ekene register holds, so no case can pass it"]'::jsonb, 0, 'MAX_POISSON_MEAN is a stated cap, and the refusal says in its own words: above that the normal safetyStock serves. The cap is a design limit, and nothing about printing, probabilities failing or the Ekene register sets it; a mean of exactly 500 is accepted.'),
  ('materials', 'advanced', 'final', null, 31, 'Which subject does this course leave to the uncertainty course, and what does it take in its place?', '["Safety stock under normal demand; this course takes a stated safety stock for each stocked item", "Failure rates from field data; this course samples each failure rate on a stated seed", "Distributions and Monte Carlo as a subject; this course applies the canonical sampler to lead-time risk", "The Poisson table; this course reads Poisson probabilities from MIL-HDBK-338B alone"]'::jsonb, 2, 'The uncertainty course owns distributions, correlation and Monte Carlo as a subject; the engine uses the canonical seeded sampler of lib/stats for lead-time risk only. Safety stock is computed here at the Professional tier; failure rates belong to the rotating course and are stated; the engine computes its own Poisson table.'),
  ('materials', 'advanced', 'final', null, 32, 'What is the engine''s stated convention for lead-time risk, and what alternative does the course set beside it?', '["One demand rate held for the whole lead time; the alternative is a fresh demand draw every day", "A fresh demand draw every day; the alternative is one demand rate held for the whole lead time drawn", "A normal lead-time demand; the alternative is a pair of stated triangles", "The lead time drawn after the demand rate; the alternative is the lead time drawn first in each iteration"]'::jsonb, 0, 'The engine holds one rate a lead time, so a busy spell stays busy until the order lands; a fresh daily draw is the alternative, which would narrow the spread. The engine samples stated triangles, and it draws the lead time first, then the demand rate.'),
  ('materials', 'advanced', 'final', null, 33, 'A stock policy is written for the mechanical seal. Which entry does the course accept as complete?', '["Its triangles, one rate a lead time, a reorder point of 3, and each sampled figure with seed 20270301 and 20000 draws", "Its triangles and a reorder point of 3, with the stockout probability of 0.058600 as a certain figure", "A reorder point of 3.062282, the engine''s answer, with the triangles left out as already known", "Its mean lead-time demand of 1.986608 seals and a reorder point of 3, with no seed needed"]'::jsonb, 0, 'A policy names every stated input, the convention the figures rest on, and each sampled figure with its seed and draws. A sampled stockout probability is an estimate that is not certain; 3.062282 is itself a sampled figure that needs its inputs beside it; a mean alone without its seed cannot be reproduced.'),
  ('materials', 'advanced', 'final', null, 34, 'What does the engine''s cap MAX_DECIMALS of 6 limit?', '["The decimals the engine prints for money inside each of its messages", "The decimals of any stated input that the engine will accept at all", "The decimals a sampled figure keeps before it is compared with another", "The decimals to which a safety factor may be read from a table"]'::jsonb, 3, 'MAX_DECIMALS caps safetyFactorRounding.decimals; seven is refused in the engine''s words: safetyFactorRounding.decimals must be a whole number from 0 to 6; got 7. Money prints to the cent inside a message, stated inputs are taken as given, and the cap plays no part in the sampled figures.'),
  ('materials', 'advanced', 'final', null, 35, 'Which pair of terms does this course''s vocabulary legislate for a sampled lead time?', '["Its P90 is the high figure, the 90th percentile of the sorted draws, and the risk sits at its P90 end", "Its P90 is the mean of all the draws, and its P10 is the median of the sorted draws of the run", "Its P90 is the low figure and its P10 the high one, where the stockout risk sits", "Its P90 is the stated maximum of the triangle, and its P10 is the stated minimum of it"]'::jsonb, 2, 'For a sampled lead time or demand the P90 is the low figure, met or exceeded in 90 percent of draws, and the stockout risk sits at the P10 end. In conversation the ninetieth percentile is a high figure; this course binds the platform''s convention. No percentile is the mean, the median of another label, or a stated end of a triangle.'),
  ('materials', 'advanced', 'final', null, 36, 'What does the course mean by "service level" wherever it writes the phrase?', '["The probability of no shortage with the stated spares, whatever call made it", "It always names its measure: the cycle service level or the fill rate", "Any measure of how well stock serves, left for the context to make clear", "The share of demand met from stock, which is the only measure the engine uses"]'::jsonb, 1, 'The vocabulary rule: a service level always names its measure, the cycle service level (the probability of no stockout in a cycle) or the fill rate (the fraction of demand met from stock). Leaving it to context is what the rule forbids, and the engine computes both measures.'),
  ('materials', 'advanced', 'final', null, 37, 'Every refusal the engine returns is an object with error and field. How does its message begin?', '["With the name of the field it refuses, then the exact condition that failed", "With a numbered error code, then the golden case that the input happened to match", "With the function''s name, then a list of every single input that the call stated", "With the word error, then the value as it was typed and the default that it replaced"]'::jsonb, 0, 'The message starts with the name of the field it refuses and states the condition, in the form <field> must <condition>; got <value>, or, for an unknown key, that it is not an accepted key with the accepted keys listed. There are no error codes, no input listings, and nothing is replaced.'),
  ('materials', 'advanced', 'final', null, 38, 'Which of these did the course NOT read, as its validation record states?', '["MIL-HDBK-338B, which is read only through its lamp example on p. 5-27", "Harris 1913, which is read only through its 1990 Operations Research reprint", "The five MIT lectures, which are cited by lecture and slide for their figures", "Silver, Pyke and Thomas and Nahmias, which are not publicly readable"]'::jsonb, 3, 'The record says, verbatim: Not used: Silver, Pyke and Thomas (4th ed., CRC 2017) and Nahmias are not publicly readable, so not read or cited. MIL-HDBK-338B, Harris 1913 in its 1990 reprint and the MIT lectures were each read on 2026-09-27; the lectures are cited by lecture and slide.'),
  ('materials', 'advanced', 'final', null, 39, 'The ESP motor is class V under the Ekene criticality policy and ranks first by annual usage value, at 370000.000000 in class A. What do those two classes say about how many spares to hold?', '["Four spares, since class V items hold one spare for each of the four criteria that the policy scores", "Nothing: both say the motor matters and costs, and the spares come from the insurance model", "Two spares, one for class V and one for class A, whatever the failure rate is", "Six spares, since the policy stocks any item in both class V and class A out to the search limit"]'::jsonb, 1, 'A criticality class is of the stated policy and an ABC class is a stated cut-off on stated usage; neither sizes a spare. The number of spares is the insurance model''s cheapest stock at a stated failure rate, lead time and costs, four for the motor. No class rule sets a count.'),
  ('materials', 'advanced', 'final', null, 40, 'Why does the insurance call return the mean number of orders outstanding beside its table?', '["The number of spares the engine recommends, rounded up to a whole spare for the policy to hold", "Every probability, the expected units down and the downtime cost in the table rest on that one mean", "It is the expected downtime a year in days, read directly from the Poisson table of orders outstanding", "A fill rate with no spares, which the table then carries down each row of spares"]'::jsonb, 1, 'The orders outstanding are Poisson with that mean, so each probability of no shortage, fill rate and expected units down, and so each downtime cost, follows from it; with no spares the expected units down equal it. It is no count of spares, no number of days and no fill rate: with no spares the fill rate is 0.000000.'),
  ('materials', 'advanced', 'final', null, 41, 'How does the probability of no shortage with 2 spares for the handbook lamps, 0.985612, tie the insurance model to MIL-HDBK-338B?', '["It is the handbook''s printed 0.986 carried into the engine as a stated input", "It is the handbook''s chance of two or fewer failures at the same mean of 0.500000, reproduced", "It is the fill rate with 2 spares, which the handbook then calls the reliability of the whole mission", "It is a Monte Carlo estimate on the handbook''s own seed, which the engine then reproduces draw by draw"]'::jsonb, 1, 'Restated as 0.365 failures a year over a lead time of 500 days and 365 days a year, the orders outstanding have the lamp mean of 0.500000, and P(X <= 2) = 0.985612 is the handbook''s mission reliability, which it prints as 0.986. The fill rate with 2 spares is the no-shortage probability with one spare fewer, a smaller figure. Nothing printed is an input; the handbook states no seed and nothing here is sampled.'),
  ('materials', 'advanced', 'final', null, 42, 'Which statement describes the engine''s figures on the stated inputs of the course?', '["Each is a forecast of what will fail or be used on the Ekene field in the coming year", "Each is what the stated inputs give, and none is a forecast, an audit of the register or a supplier''s promise", "Each is a supplier''s promise of price and lead time, which the engine checks against the register", "Each is the policy itself, since the engine decides which items to stock and at which target"]'::jsonb, 1, 'A class, an EOQ, a safety stock and a number of spares are each what the stated criteria, costs, demands and targets give; none is a forecast, an audit or a promise, and each is quoted with its inputs. The engine writes no stock policy: the policy is the user''s, written down and reviewed.');
